fn get_at(xs: List[Int], i: Int) -> Option[Int]
  requires ((i >= 0) and (i < len(xs)))
  ensures (result != None)
  effects pure
  example (get_at([10, 20, 30], 0) == Some(10))
  example (get_at([10, 20, 30], 1) == Some(20))
  example (get_at([10, 20, 30], 2) == Some(30))
{
  match xs { [] => None [h, ..t] => if (i == 0) then Some(h) else get_at(t, (i - 1)) }
}

fn index_of(xs: List[Int], x: Int) -> Int
  requires contains(xs, x)
  ensures ((result >= 0) and (result < len(xs)))
  ensures (get_at(xs, result) == Some(x))
  effects pure
  example (index_of([4, 7, 9], 7) == 1)
  example (index_of([3, 3, 3], 3) == 0)
{
  match xs { [] => 0 [h, ..t] => if (h == x) then 0 else (1 + index_of(t, x)) }
}

