fn longest_run_helper(xs: List[Int], current_run: Int, max_run: Int) -> Int
  requires ((current_run >= 1) and (max_run >= 0))
  ensures (result >= 1)
  effects pure
  example (longest_run_helper([], 1, 0) == 1)
  example (longest_run_helper([1, 2], 1, 1) == 1)
  example (longest_run_helper([2, 2, 3], 2, 1) == 3)
{
  match xs { [] => if (current_run > max_run) then current_run else max_run [h, ..t] => match t { [] => if (current_run > max_run) then current_run else max_run [h2, ..rest] => if (h == h2) then longest_run_helper(t, (current_run + 1), max_run) else longest_run_helper(t, 1, if (current_run > max_run) then current_run else max_run) } }
}

fn longest_run(xs: List[Int]) -> Int
  requires (len(xs) > 0)
  ensures (result >= 1)
  effects pure
  example (longest_run([1, 1, 2, 2, 2, 3]) == 3)
  example (longest_run([7]) == 1)
{
  match xs { [h, ..t] => longest_run_helper(t, 1, 0) _ => 1 }
}

