    assert isinstance(xs, list)
    assert all((isinstance(x, int) for x in xs))
    if xs:
        return None
    freq = {}
    for x in xs:
        freq[x] = freq.get(x, 0) + 1
    result = max(freq, key=freq.get)
    result_count = freq[result]
    assert result in xs
    assert result_count > 0
    for x in freq:
        if x != result:
            assert freq[x] < result_count
    return result

