fn count_element(xs: List[Int], x: Int) -> Int
  requires (len(xs) >= 0)
  ensures (result == count(xs, x))
  effects pure
  example (count_element([1, 2, 2, 3], 2) == 2)
  example (count_element([1, 2, 3], 4) == 0)
{
  match xs { [] => 0 [h, ..t] => if (h == x) then (1 + count_element(t, x)) else count_element(t, x) }
}

fn get_max_by_count_helper(xs: List[Int], candidates: List[Int]) -> Int
  requires (len(candidates) > 0)
  requires forall c in candidates: contains(xs, c)
  ensures contains(candidates, result)
  ensures forall c in candidates: (count_element(xs, c) <= count_element(xs, result))
  effects pure
  example (get_max_by_count_helper([1, 2, 2, 3], [1, 2, 3]) == 2)
{
  match candidates { [] => 0 [h, ..t] => match t { [] => h _ => if (count_element(xs, h) >= count_element(xs, get_max_by_count_helper(xs, t))) then h else get_max_by_count_helper(xs, t) } }
}

fn get_max_by_count(xs: List[Int]) -> Int
  requires (len(xs) > 0)
  ensures contains(xs, result)
  ensures forall x in xs: (count_element(xs, x) <= count_element(xs, result))
  effects pure
  example (get_max_by_count([1, 2, 2, 3]) == 2)
{
  get_max_by_count_helper(xs, xs)
}

fn most_frequent(xs: List[Int]) -> Option[Int]
  requires ((len(xs) == 0) or exists x in xs: forall y in xs: ((x == y) or (count(xs, x) > count(xs, y))))
  ensures match result { None => (len(xs) == 0) Some(x) => (contains(xs, x) and forall y in xs: (count(xs, y) <= count(xs, x))) }
  effects pure
  example (most_frequent([]) == None)
  example (most_frequent([1, 2, 2, 3]) == Some(2))
{
  match xs { [] => None _ => Some(get_max_by_count(xs)) }
}

