  ensures (result == count(xs, x))
  effects pure
  example (occurrences([1, 2, 2, 3], 2) == 2)
  example (occurrences([], 5) == 0)
{
  match xs { [] => 0 [h, ..t] => if (h == x) then (1 + occurrences(t, x)) else occurrences(t, x) }
}

fn max_count(xs: List[Int], candidates: List[Int]) -> Int
  requires (len(candidates) > 0)
  ensures (result >= 1)
  ensures forall v in candidates: (occurrences(xs, v) <= result)
  ensures exists v in candidates: (occurrences(xs, v) == result)
  effects pure
  example (max_count([1, 2, 2, 3], [1, 2, 2, 3]) == 2)
  example (max_count([5], [5]) == 1)
{
  match candidates { [] => 0 [h, ..t] => match t { [] => occurrences(xs, h) [_, .._] => if (occurrences(h, xs) >= max_count(xs, t)) then occurrences(xs, h) else max_count(xs, t) } }
}

fn find_most(xs: List[Int], target: Int) -> Int
  requires exists v in xs: (occurrences(xs, v) == target)
  ensures (occurrences(xs, result) == target)
  effects pure
  example (find_most([1, 2, 2, 3], 2) == 2)
  example (find_most([5], 1) == 5)
{
  match xs { [] => 0 [h, ..t] => if (occurrences(xs, h) == target) then h else find_most(t, target) }
}

fn most_frequent(xs: List[Int]) -> Option[Int]
  requires ((len(xs) == 0) or exists v in xs: forall w in xs: ((w == v) or (occurrences(xs, w) < occurrences(xs, v))))
  ensures (((len(xs) == 0) and (result == None)) or ((len(xs) > 0) and exists v in xs: ((result == Some(v)) and forall w in xs: ((w == v) or (occurrences(xs, w) < occurrences(xs, v))))))
  effects pure
  example (most_frequent([1, 2, 2, 3]) == Some(2))
  example (most_frequent([]) == None)
{
  match xs { [] => None [_, .._] => Some(find_most(xs, max_count(xs, xs))) }
}

