  ensures (len(result) == (len(xs) - 1))
  ensures forall y in result: contains(xs, y)
  effects pure
  example (remove_first([3, 9, 1], 9) == [3, 1])
  example (remove_first([9], 9) == [])
{
  match xs { [] => [] [h, ..t] => if (t == x) then t else ([h] ++ remove_first(t, x)) }
}

fn second_largest(xs: List[Int]) -> Option[Int]
  requires distinct(xs)
  ensures match result { None => (len(xs) < 2) Some(x) => (contains(xs, x) and exists y in xs: (y > x)) }
  effects pure
  example (second_largest([3, 9, 1]) == Some(3))
  example (second_largest([4]) == None)
  example (second_largest([1, 2]) == Some(1))
{
  match max_element(xs) { None => None Some(max_val) => match max_element(remove_first(xs, max_val)) { None => None Some(second) => Some(second) } }
}

fn max_element(xs: List[Int]) -> Option[Int]
  requires (len(xs) >= 0)
  ensures match result { None => (len(xs) == 0) Some(m) => (contains(xs, m) and forall x in xs: (x <= m)) }
  effects pure
  example (max_element([]) == None)
  example (max_element([3, 9, 1]) == Some(9))
  example (max_element([5]) == Some(5))
{
  match xs { [] => None [h, ..t] => match max_element(t) { None => Some(h) Some(m) => Some(if (h > m) then h else m) } }
}

